package com.bank.jvm.shenandoah;

import java.math.BigDecimal;
import java.util.logging.Logger;

public class CardAuthSimulator {
    private static final Logger log = Logger.getLogger(CardAuthSimulator.class.getName());

    public static void main(String[] args) {
        PauseObserver observer = new PauseObserver();
        log.info("Bank: National Bank of India — Shenandoah card-auth simulator");
        observer.snapshot("before");

        // Long-lived BIN table: stays in the old generation for the whole run.
        BinLookupTable binTable = new BinLookupTable(100_000);
        log.info(() -> "Loaded BIN table with " + binTable.size() + " entries");

        // Short-lived authorization requests: young-generation churn.
        long approved = 0;
        for (int i = 0; i < 8_000_000; i++) {
            AuthRequest req = new AuthRequest("CARD-" + (i % 500_000),
                    new BigDecimal("50000"), binTable);
            if (req.authorize()) approved++;
            if (i % 2_000_000 == 0) observer.snapshot("during");
        }

        log.info(() -> "Approved authorizations: " + approved);
        observer.snapshot("after");
        log.info("Shenandoah compacted concurrently; young GC reclaimed the auth churn");
    }
}

// ─── Would be in BinLookupTable.java in a real project ───
class BinLookupTable {
    private final int[] binRisk; // long-lived lookup data

    BinLookupTable(int entries) {
        this.binRisk = new int[entries];
        for (int i = 0; i < entries; i++) binRisk[i] = (i * 31) % 100;
    }
    int size() { return binRisk.length; }
    int riskFor(int bin) { return binRisk[Math.floorMod(bin, binRisk.length)]; }
}

// ─── Would be in AuthRequest.java in a real project ───
class AuthRequest {
    private final String cardToken;
    private final BigDecimal amount;
    private final BinLookupTable binTable;
    private final byte[] payload = new byte[64]; // short-lived request payload

    AuthRequest(String cardToken, BigDecimal amount, BinLookupTable binTable) {
        this.cardToken = cardToken;
        this.amount = amount;
        this.binTable = binTable;
    }
    boolean authorize() {
        int risk = binTable.riskFor(cardToken.hashCode());
        int weight = payload.length + amount.intValue() % 7;
        return (risk + weight) % 10 < 9; // approve 90%
    }
}
