package com.bank.jvm.shenandoah;

import java.lang.management.GarbageCollectorMXBean;
import java.lang.management.ManagementFactory;
import java.util.logging.Logger;

class PauseObserver {
    private static final Logger log = Logger.getLogger(PauseObserver.class.getName());

    void snapshot(String phase) {
        long count = 0, timeMs = 0;
        for (GarbageCollectorMXBean gc : ManagementFactory.getGarbageCollectorMXBeans()) {
            count += Math.max(gc.getCollectionCount(), 0);
            timeMs += Math.max(gc.getCollectionTime(), 0);
        }
        final long c = count, t = timeMs;
        log.info(() -> "GC [" + phase + "] collections=" + c + " totalPauseMs=" + t);
    }
}
